package com.kuaixietech.storage;
import com.kuaixietech.security.DomainAccessGuard;
import java.util.*;
import java.io.*;
import javax.imageio.ImageIO;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
@Service
public class PrivateUploads {
 public static final int LIMIT=10*1024*1024;
 private static final Set<String> PURPOSES=Set.of("store_license","insurance_certificate","dispute_evidence","product_image");
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final PrivateObjectStorage storage;
 private UploadBindings bindings;private UploadLifecycle lifecycle;private com.kuaixietech.coupler.CouplerModeGate mode;
 public PrivateUploads(JdbcTemplate db,DomainAccessGuard guard,PrivateObjectStorage storage){this.db=db;this.guard=guard;this.storage=storage;}
 @Autowired public void bindings(UploadBindings bindings,UploadLifecycle lifecycle,com.kuaixietech.coupler.CouplerModeGate mode){this.bindings=bindings;this.lifecycle=lifecycle;this.mode=mode;}
 public Map<String,Object> upload(MultipartFile file,String purpose){String user=guard.requireActiveProfile();if(!PURPOSES.contains(purpose)||file.isEmpty()||file.getSize()>LIMIT)throw new IllegalArgumentException("UPLOAD_INPUT_REJECTED");try{byte[] bytes;try(var stream=file.getInputStream()){bytes=stream.readNBytes(LIMIT+1);}if(bytes.length>LIMIT||bytes.length!=file.getSize())throw new IllegalArgumentException("UPLOAD_INPUT_REJECTED");String mime=mime(bytes);boolean image=purpose.equals("product_image");if(image)verifyImage(bytes,mime);if(mode!=null)mode.requireLiveNewCall("private_upload");String id=UUID.randomUUID().toString(),key="private/"+user+"/"+id;var binding=storage.active();storage.put(binding,key,mime,bytes);String name=Objects.toString(file.getOriginalFilename(),"document").replaceAll("[\\p{Cntrl}/\\\\]","_");if(name.length()>200)name=name.substring(0,200);String sha=HexFormat.of().formatHex(PrivateObjectStorage.digest("SHA-256",bytes));if(db.update("INSERT INTO t_community_uploads(id,user_id,kind,storage_key,content_type,purpose,sha256,byte_size,original_name) VALUES(?,?,?,?,?,?,?,?,?)",id,user,image?"image":"document",storage.reference(binding,key),mime,purpose,sha,bytes.length,name)!=1)throw new IllegalStateException("UPLOAD_METADATA_UNCONFIRMED");var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("purpose",purpose);result.put("contentType",mime);result.put("byteSize",bytes.length);result.put("sha256",sha);if(image)result.put("publicPath","/public/media/"+id);return result;}catch(IOException e){throw new IllegalStateException("UPLOAD_READ_FAILED");}}
 public List<Map<String,Object>> mine(String purpose){String user=guard.requireActiveProfile();if(!PURPOSES.contains(purpose))throw new IllegalArgumentException("UPLOAD_PURPOSE_REJECTED");return db.queryForList("SELECT id,purpose,content_type,byte_size,original_name,consumed_at,created_at FROM t_community_uploads WHERE user_id=? AND purpose=? AND kind IN('document','image') ORDER BY created_at DESC,id DESC LIMIT 100",user,purpose).stream().map(row->{var result=new LinkedHashMap<String,Object>(row);if(purpose.equals("product_image"))result.put("publicPath","/public/media/"+row.get("id"));return (Map<String,Object>)result;}).toList();}
 public record Document(byte[] bytes,String contentType){}
 private Document verified(Map<String,Object> row){if(!Set.of("document","image").contains(row.get("kind"))||!(row.get("byte_size") instanceof Number length)||length.longValue()<1||length.longValue()>LIMIT||!Objects.toString(row.get("sha256"),"").matches("[a-f0-9]{64}"))throw new IllegalStateException("UPLOAD_UNVERIFIED");byte[] bytes=storage.get(row.get("storage_key").toString(),LIMIT);if(!HexFormat.of().formatHex(PrivateObjectStorage.digest("SHA-256",bytes)).equals(row.get("sha256"))||bytes.length!=length.intValue())throw new IllegalStateException("UPLOAD_CONTENT_MISMATCH");String mime=mime(bytes);if("image".equals(row.get("kind")))verifyImage(bytes,mime);return new Document(bytes,mime);}
 public Document download(String id){String user=guard.requireActiveProfile();var rows=db.queryForList("SELECT user_id,kind,purpose,storage_key,content_type,sha256,byte_size FROM t_community_uploads WHERE id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"UPLOAD_UNAVAILABLE");var row=rows.getFirst();if(!user.equalsIgnoreCase(Objects.toString(row.get("user_id"),""))&&!("product_image".equals(row.get("purpose"))&&bindings!=null&&bindings.orderParticipant(id,user)))guard.requireAdmin();return verified(row);}
 public Document publicImage(String id){if(!id.matches("[a-f0-9-]{36}"))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"UPLOAD_UNAVAILABLE");var rows=db.queryForList("SELECT u.kind,u.purpose,u.storage_key,u.content_type,u.sha256,u.byte_size FROM t_community_uploads u WHERE u.id=? AND u.kind='image' AND u.purpose='product_image' AND u.content_type IN('image/jpeg','image/png') AND EXISTS(SELECT 1 FROM t_products p JOIN t_profiles s ON s.id=p.owner_id WHERE p.owner_id=u.user_id AND p.status='on' AND p.stock>0 AND s.deleted_at IS NULL AND s.carrier_verify_status='approved' AND (s.banned_until IS NULL OR s.banned_until<=CURRENT_TIMESTAMP(3)) AND JSON_CONTAINS(p.image_urls,JSON_QUOTE(?)) AND NOT EXISTS(SELECT 1 FROM t_store_products sp JOIN t_stores st ON st.id=sp.store_id WHERE sp.product_id=p.id AND (st.owner_id<>p.owner_id OR st.status<>'active')))",id,"/public/media/"+id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"UPLOAD_UNAVAILABLE");return verified(rows.getFirst());}
 public Map<String,String> remove(String id){String user=guard.requireActiveProfile();if(mode!=null)mode.requireLiveNewCall("delete_unused_upload");if(lifecycle==null)throw new IllegalStateException("UPLOAD_DELETE_SERVICE_UNAVAILABLE");var deletion=lifecycle.begin(id,user);if(deletion.status().equals("deleted"))return Map.of("id",id,"status","deleted");try{storage.delete(deletion.storageKey());lifecycle.complete(deletion);return Map.of("id",id,"status","deleted");}catch(RuntimeException e){lifecycle.unconfirmed(deletion);return Map.of("id",id,"status","deleting");}}
 public List<Map<String,Object>> deletions(){String user=guard.requireActiveProfile();if(lifecycle==null)throw new IllegalStateException("UPLOAD_DELETE_SERVICE_UNAVAILABLE");return lifecycle.mine(user);}
 static void verifyImage(byte[] bytes,String mime){if(!Set.of("image/jpeg","image/png").contains(mime))throw new IllegalArgumentException("UPLOAD_IMAGE_REQUIRED");try(var input=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("UPLOAD_IMAGE_INVALID");var reader=readers.next();try{reader.setInput(input,true,true);int width=reader.getWidth(0),height=reader.getHeight(0);if(width<1||height<1||width>12000||height>12000||(long)width*height>25_000_000L)throw new IllegalArgumentException("UPLOAD_IMAGE_DIMENSIONS_REJECTED");var decoded=reader.read(0);if(decoded==null||decoded.getWidth()!=width||decoded.getHeight()!=height)throw new IllegalArgumentException("UPLOAD_IMAGE_INVALID");decoded.flush();}finally{reader.dispose();}}catch(IOException e){throw new IllegalArgumentException("UPLOAD_IMAGE_INVALID");}}
 static String mime(byte[] b){if(b.length>=8&&b[0]==(byte)0x89&&new String(b,1,3,java.nio.charset.StandardCharsets.US_ASCII).equals("PNG")&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "image/png";if(b.length>=3&&b[0]==(byte)0xff&&b[1]==(byte)0xd8&&b[2]==(byte)0xff)return "image/jpeg";if(b.length>=5&&new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))return "application/pdf";throw new IllegalArgumentException("UPLOAD_CONTENT_TYPE_REJECTED");}
}
